def validate_record(row):
    if not isinstance(row.get("age"), (int, float)):
        raise ValueError("age must be numeric")
    if not 0 <= row["age"] <= 120:
        raise ValueError("age outside the declared contract")
    if row.get("income") not in ("<=50K", ">50K"):
        raise ValueError("unknown target label")
    return True


print(validate_record({"age": 39, "income": "<=50K"}))
# Range 0..120 is this exercise's declared rule, not a universal rule.

from statistics import median
from math import isfinite


class MedianImputer:
    def fit(self, values):
        seen = [v for v in values if v is not None]
        if not seen or not all(isfinite(v) for v in seen):
            raise ValueError("Finite observed training values required")
        self.fill_ = median(seen)
        return self

    def transform(self, values):
        if not hasattr(self, "fill_"):
            raise RuntimeError("Call fit first")
        return [self.fill_ if v is None else v for v in values]


imputer = MedianImputer().fit([10, 20, None, 90])
print(imputer.transform([None, 140]))  # [20, 140]

def oof_means(categories, targets, folds):
    result = [None] * len(categories)
    for fold in sorted(set(folds)):
        train = [i for i in range(len(folds)) if folds[i] != fold]
        if not train:
            raise ValueError("Each fold needs training observations")
        prior = sum(targets[i] for i in train) / len(train)
        totals, counts = {}, {}
        for i in train:
            key = categories[i]
            totals[key] = totals.get(key, 0) + targets[i]
            counts[key] = counts.get(key, 0) + 1
        for i in range(len(folds)):
            if folds[i] == fold:
                key = categories[i]
                result[i] = totals[key] / counts[key] if key in counts else prior
    return result


print(oof_means(["A", "A", "B", "B"], [1, 0, 1, 0], [0, 1, 0, 1]))
# [0.0, 1.0, 0.0, 1.0]; even the prior uses fold-training labels only.

from math import sin, cos, pi, hypot


def hour_pair(hour):
    if not 0 <= hour < 24:
        raise ValueError("Hour must be in [0,24)")
    phase = 2 * pi * hour / 24
    return sin(phase), cos(phase)


a, b = hour_pair(23), hour_pair(0)
print(round(hypot(a[0] - b[0], a[1] - b[1]), 6))  # 0.261052

